const net = require('node:net');
const original = net.Socket.prototype.connect;
net.Socket.prototype.connect = function(...args) {
  const opts = net._normalizeArgs(args)[0];
  if (!opts.path && !['127.0.0.1','localhost','::1'].includes(opts.host || 'localhost')) {
    const err = new Error('Benchmark process denied non-loopback network');
    err.code = 'ERR_BENCH_NETWORK_DENIED';
    process.stderr.write('BENCH_NETWORK_DENIED\n');
    throw err;
  }
  return original.apply(this,args);
};

