import {readFileSync,writeFileSync} from 'node:fs';
import {parseEnv} from 'node:util';
import http from 'node:http';
import https from 'node:https';
import {spawn} from 'node:child_process';
import {createHash} from 'node:crypto';
const config=parseEnv(readFileSync('/home/alp/dev/projects/goodwatch/goodwatch-monorepo/goodwatch-webapp/.env','utf8'));
const upstream=new URL(`http://${config.CRATE_HOSTS.split(',')[0].trim()}:${config.CRATE_PORT||'4200'}`);
const counts={sqlReads:0,cacheHits:0,blobReads:0,sqlBlocked:0,browserBlocked:0};
const cache=new Map();let app=null,stage='none';
const proxy=http.createServer(async(req,res)=>{
 const chunks=[];for await(const c of req)chunks.push(c);const body=Buffer.concat(chunks);
 let sql;try{sql=JSON.parse(body).stmt;}catch{}
 const path=req.url.split('?')[0];
 const blob=req.method==='GET'&&/^\/_blobs\/[a-z_]+\/[a-f0-9]{40}$/.test(path);
 const read=req.method==='POST'&&path==='/_sql'&&/^\s*(SELECT|WITH)\b/i.test(sql||'')&&!/\b(INSERT|UPDATE|DELETE|ALTER|DROP|CREATE|GRANT|REVOKE|COPY|REFRESH|BEGIN|COMMIT)\b/i.test(sql||'')&&!(sql||'').trim().replace(/;\s*$/,'').includes(';');
 if(!blob&&!read){counts.sqlBlocked++;res.writeHead(403,{'Content-Type':'application/json'});res.end(JSON.stringify({error:{message:'Benchmark read-only proxy refused request',code:4030}}));return;}
 const key=createHash('sha256').update(req.method+req.url).update(body).digest('hex');
 if(cache.has(key)){counts.cacheHits++;const saved=cache.get(key);res.writeHead(saved.status,saved.headers);res.end(saved.body);return;}
 if(blob)counts.blobReads++;else counts.sqlReads++;
 const outgoing=http.request(new URL(req.url,upstream),{method:req.method,headers:{'Content-Type':'application/json',Authorization:`Basic ${Buffer.from(`${config.CRATE_USER}:${config.CRATE_PASS}`).toString('base64')}`}},response=>{
  const chunks=[];response.on('data',c=>chunks.push(c));response.on('end',()=>{const saved={status:response.statusCode,headers:response.headers,body:Buffer.concat(chunks)};if(response.statusCode===200)cache.set(key,saved);res.writeHead(saved.status,saved.headers);res.end(saved.body);});
 });outgoing.on('error',()=>{res.writeHead(502);res.end();});outgoing.end(body);
});
const tls=https.createServer({key:readFileSync('/tmp/gw-opened-bench.key'),cert:readFileSync('/tmp/gw-opened-bench.crt')},(req,res)=>{
 if(!['GET','HEAD'].includes(req.method)||['/api/poster-impressions','/api/og-image-warm','/api/e'].includes(req.url.split('?')[0])){counts.browserBlocked++;res.writeHead(204);res.end();return;}
 const outgoing=http.request({hostname:'127.0.0.1',port:34121,path:req.url,method:req.method,headers:{...req.headers,'x-forwarded-proto':'https'}},response=>{res.writeHead(response.statusCode,response.headers);response.pipe(res);});outgoing.on('error',()=>{res.writeHead(502);res.end();});req.pipe(outgoing);
});
async function switchStage(next){
 if(app){const previous=app;await new Promise(resolve=>{previous.once('exit',resolve);previous.kill('SIGTERM');});}
 stage=next;const cwd=next==='baseline'?'/tmp/gw-opened-baseline/goodwatch-webapp':'/home/alp/dev/projects/goodwatch/streaming-refresh-implementation/goodwatch-webapp';
 const env={PATH:process.env.PATH,NODE_ENV:'production',NODE_OPTIONS:'--require /tmp/gw-streaming-perf-deny.cjs',PORT:'34121',HOST:'127.0.0.1',APP_ORIGIN:'https://127.0.0.1:34120',CRATE_HOSTS:'127.0.0.1',CRATE_PORT:'34122',CRATE_USER:config.CRATE_USER,CRATE_PASS:config.CRATE_PASS,QDRANT_URL:'http://127.0.0.1:34124',BETTER_AUTH_ENABLED:'false',POSTHOG_DISABLED:'true'};
 app=spawn('./node_modules/.bin/remix-serve',['./build/server/index.js'],{cwd,env,stdio:'inherit'});app.once('exit',()=>{if(app===app){};});console.log('STAGE',stage);
}
const control=http.createServer(async(req,res)=>{
 if(req.method==='POST'&&['/baseline','/feature'].includes(req.url)){await switchStage(req.url.slice(1));res.end('started');return;}
 if(req.method==='GET'&&req.url==='/stats'){res.setHeader('Content-Type','application/json');res.end(JSON.stringify({stage,...counts,cacheEntries:cache.size}));return;}
 res.writeHead(404);res.end();
});
await Promise.all([new Promise(r=>proxy.listen(34122,'127.0.0.1',r)),new Promise(r=>tls.listen(34120,'127.0.0.1',r)),new Promise(r=>control.listen(34123,'127.0.0.1',r))]);
console.log('GUARDED_PERF_SERVER_READY');
for(const signal of ['SIGTERM','SIGINT'])process.on(signal,()=>{writeFileSync('/tmp/gw-streaming-perf-proxy-counts.json',JSON.stringify(counts));app?.kill();proxy.close();tls.close();control.close();});

