import lighthouse from '/home/alp/.npm/_npx/1722e863ebfd623b/node_modules/lighthouse/core/index.js';
import puppeteer from '/home/alp/.npm/_npx/1722e863ebfd623b/node_modules/puppeteer-core/lib/puppeteer/puppeteer-core.js';
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {createHash} from 'node:crypto';
const stage=process.argv[2];const root='/home/alp/dev/projects/goodwatch/streaming-refresh-implementation';
const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z');
const out=`${root}/goodwatch-benchmark/results/${stamp}-lighthouse-streaming-${stage}-matched`;
mkdirSync(out+'/lighthouse',{recursive:true});
const source=readFileSync(`${root}/goodwatch-benchmark/results/20261026T015809Z-lighthouse-streaming-opened-demand-https/lighthouse-urls.txt`,'utf8');
const urls=source.trim().split('\n').map(line=>{const [label,url]=line.trim().split(/\s+/);return [label,'https://127.0.0.1:34120'+new URL(url).pathname+new URL(url).search];});
const policy=[];const browser=await puppeteer.launch({executablePath:'/home/alp/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome',headless:true,acceptInsecureCerts:true,args:['--no-sandbox','--disable-dev-shm-usage','--hide-scrollbars','--ignore-certificate-errors','--disable-background-networking','--disable-component-update','--disable-sync','--disable-default-apps','--no-first-run','--no-default-browser-check']});
writeFileSync(out+'/meta.json',JSON.stringify({kind:'lighthouse',label:`streaming-${stage}-matched`,target_url:'https://127.0.0.1:34120',stage,started_at:new Date().toISOString(),lighthouse:{runs:1,where:'local',cpu_slowdown:2.7},browser:await browser.version(),guard:'Provided Puppeteer page intercepts requests before transport; only GET/HEAD to localTLS or image.tmdb.org allowed; local demand and telemetry sinks blocked. App outbound sockets restricted to loopback; SQL proxy readonly and shared response cache.'},null,2));
console.log('RUN_DIRECTORY',out);
try{
 for(const [label,url] of urls){
  const context=await browser.createBrowserContext();const page=await context.newPage();await page.setBypassServiceWorker(true);await page.setRequestInterception(true);
  const events={label,allowed:0,blocked:[],failed:[],mainStatus:null};
  page.on('request',async request=>{
   try{
    const parsed=new URL(request.url());const safeMethod=['GET','HEAD'].includes(request.method());
    const local=parsed.origin==='https://127.0.0.1:34120';const image=parsed.protocol==='https:'&&parsed.hostname==='image.tmdb.org';
    const sink=local&&['/api/e','/api/poster-impressions','/api/og-image-warm'].includes(parsed.pathname);
    if(!safeMethod||(!local&&!image&&!['data:','blob:','about:'].includes(parsed.protocol))||sink){
     events.blocked.push({method:request.method(),origin:parsed.origin,resourceType:request.resourceType(),sink});
     await request.respond({status:204,body:''});return;
    }
    events.allowed++;await request.continue();
   }catch(error){if(!request.isInterceptResolutionHandled())await request.abort('blockedbyclient');}
  });
  page.on('requestfailed',r=>events.failed.push({origin:(()=>{try{return new URL(r.url()).origin;}catch{return 'opaque';}})(),resourceType:r.resourceType(),error:r.failure()?.errorText}));
  page.on('response',response=>{if(response.url()===url)events.mainStatus=response.status();});
  console.log('BEGIN',stage,label,new Date().toISOString());
  const result=await lighthouse(url,{onlyCategories:['performance'],formFactor:'mobile',logLevel:'error',throttling:{cpuSlowdownMultiplier:2.7}},undefined,page);
  mkdirSync(out+'/lighthouse/'+label,{recursive:true});writeFileSync(out+`/lighthouse/${label}/run-1.json`,JSON.stringify(result.lhr));
  policy.push(events);writeFileSync(out+'/request-policy.json',JSON.stringify(policy,null,2));
  console.log('DONE',stage,label,'status',events.mainStatus,'score',result.lhr.categories.performance.score,'requests',events.allowed,'blocked',events.blocked.length);
  await context.close();
 }
}finally{await browser.close();}
const meta=JSON.parse(readFileSync(out+'/meta.json'));meta.ended_at=new Date().toISOString();writeFileSync(out+'/meta.json',JSON.stringify(meta,null,2));
writeFileSync(`/tmp/gw-streaming-${stage}-run-path`,out);
console.log('COMPLETE',stage);
